let TOTAL_DAYS = 50;
// ===== Super Practice mock naming helper =====
// Super Practice mocks ("spmock001", "spmock002"...) are deliberately
// mixed-chapter tests. Earlier they all showed the generic, unhelpful
// name "Super Practice Mock N", which looked like it said "Mixed
// Practice" with no info about what's actually inside. This helper looks
// at the actual questions in a given mock (via their per-question
// chapter/topic tag) and builds a real name out of the 1-2 chapters that
// actually dominate that specific mock, e.g. "Number System + Time,
// Speed & Distance Mix" instead of just a number.
// Reasoning Super Practice questions have no chapter tag on them (unlike
// Math/English), so we guess the sub-topic straight from the question
// text using ordered keyword rules. Checked against real question sets
// while building this — order matters (more specific rules first).
function classifyReasoningQuestionText(text){
  const t = (text || '').toLowerCase();
  const rules = [
    [/venn diagram/, 'Venn Diagram'],
    [/transparent sheet|mirror image|water image|folded|paper fold/, 'Mirror & Water Image'],
    [/cube|dice|dices/, 'Cube & Dice'],
    [/dictionary|alphabetical order/, 'Alphabet Test'],
    [/statements? .*conclusions?|conclusions? .*statements?/, 'Syllogism'],
    [/coded as|code language|is written as|letters are jumble|number has been denoted to each/, 'Coding-Decoding'],
    [/hexagon|triangular mat|circular table|row facing|linear arrangement|face(s|d)? (north|south|east|west)? ?the centre|floor(s)?.*building|persons? work(s)? in a building/, 'Seating Arrangement'],
    [/clock|calendar|day of the week|which day|was (monday|tuesday|wednesday|thursday|friday|saturday|sunday)/, 'Clock & Calendar'],
    [/matrix/, 'Matrix'],
    [/count(ing)? (the )?number of (triangles|squares|lines|circles)|how many triangles|how many squares/, 'Figure Counting'],
    [/mathematical sign|mathematical operation|balance the given equation|interchang(ed|ing).*(sign|number)|means '?(minus|plus|divided|multiplied|add)/, 'Mathematical Operations'],
    [/logical(,)? (and )?meaningful order|logical sequence/, 'Logical Sequence'],
    [/meaningful (four|five|three|six)-letter.*word|words can be formed/, 'Word Formation'],
    [/rank(ing)?|taller than|heavier than|shorter than|position from the (left|right|top|bottom)|older than|oldest among/, 'Ranking & Order'],
    [/(started|walks|walking|ran|running) .*(north|south|east|west)|distance between|direction/, 'Direction Sense'],
    [/odd (one|word|number|pair) out|select the odd|not similar to|which .*does not belong|is different from the rest|triad.*different from the other/, 'Classification / Odd One Out'],
    [/triad|number-pair|set(s)? of numbers are related|numbers.*related in the same way/, 'Number Analogy'],
    [/word-pair|is related to.*then.*is related to|pair of terms/, 'Analogy'],
    [/related to \d+.*following a certain logic|analogous|analogy|is related to.*in the same way/, 'Analogy'],
    [/missing (number|term)|complete the series|replace the question mark|find the (next|missing)|series.*put in bracket/, 'Series'],
    [/related to.*second (letter-cluster|number|figure|word)|first .*is related to the second/, 'Analogy'],
    [/data (provided|given) in the statements? (is|are) sufficient|data sufficiency/, 'Statement Reasoning'],
    [/how is .*related to|relation(ship)? .*(family|grandmother|grandfather|mother|father|brother|sister|cousin|nephew|niece|uncle|aunt)|son-in-law|daughter-in-law|spouse of|married to/, 'Blood Relations'],
    [/in a row,|sitting in the middle of a row|neighbour of both/, 'Seating Arrangement']
  ];
  for(let i = 0; i < rules.length; i++){
    if(rules[i][0].test(t)) return rules[i][1];
  }
  return 'General Reasoning';
}
function reasoningQuestionText(item){
  if(!item) return '';
  const en = item.en || {};
  const hi = item.hi || {};
  const prompt = en.prompt || hi.prompt || item.prompt || [];
  return Array.isArray(prompt) ? prompt.join(' ') : String(prompt || '');
}
function buildSPMockLabel(items, field, num, count, prefix){
  const counts = {};
  const order = [];
  (items || []).forEach(function(it){
    const v = it && it[field];
    if(!v) return;
    if(!(v in counts)){ counts[v] = 0; order.push(v); }
    counts[v]++;
  });
  const sorted = order.slice().sort(function(a, b){ return counts[b] - counts[a]; });
  let namePart = '';
  if(sorted.length === 0){
    namePart = '';
  } else if(sorted.length === 1){
    namePart = sorted[0];
  } else {
    const top2 = sorted.slice(0, 2);
    namePart = top2.join(' + ') + (sorted.length > 2 ? ' Mix' : '');
  }
  const base = (prefix || 'Super Practice') + ' ' + num;
  const withName = namePart ? (base + ': ' + namePart) : base;
  return withName + ' (' + count + ' Qs)';
}
// ===== AI proxy endpoint =====
// The 4 AI features below (Time Coach, Strict Manager popup, AI Study
// Guide, AI Mock Analysis) all call this single Cloudflare Worker URL —
// the browser never talks to Anthropic directly and never sees the API
// key. The Worker looks at each request's "model" field and routes it to
// Claude (Anthropic). The real key lives on the Worker as a server-side
// secret. Deploy/update the included
// cloudflare-worker.js (hybrid version) at this same *.workers.dev URL —
// everything else in the app keeps working unchanged either way (inside a
// Claude.ai Artifact preview or hosted standalone, e.g. GitHub Pages).
const AI_PROXY_URL = "https://white-fire-2957.crickrttop10.workers.dev/v1/messages";
// Draw to type / Slide typing: BAND. Dobara chahiye to sirf true karo (menu item + buttons wapas aa jayenge).
const CX_DRAW_ENABLED = false;

// ---- Chat AI (Autopilot + AI reply suggest): provider chunao — proxy (default) / Gemini / Groq / OpenRouter ----
// Key sirf is phone ke localStorage me ('cx-ai-key'); Autopilot settings > "AI provider" me daalo.
// Gemini key app.js me NAHI (GitHub secret scanning + leak). Key Cloudflare Worker (gemini-worker.js) me secret hai; worker ka URL yahan daalo.
const CX_GEM_PROXY = 'https://gemini-proxy.crickrttop10.workers.dev';   // jaise 'https://gemini-proxy.<naam>.workers.dev'  (khaali = purana Claude proxy / user ki apni key)
try{ if(localStorage.getItem('cx-ai-prov') === null) localStorage.setItem('cx-ai-prov', 'gemini'); }catch(e){}
const CX_AI_DEF = { gemini: 'gemini-flash-lite-latest', groq: 'llama-3.3-70b-versatile', openrouter: 'meta-llama/llama-3.3-70b-instruct:free' };
async function cxAiCallRaw(model, system, msgs, maxTokens, forceMdl){
  let prov = 'proxy', key = '', mdl = '';
  try{ prov = localStorage.getItem('cx-ai-prov') || 'proxy'; key = (localStorage.getItem('cx-ai-key') || '').trim(); mdl = (localStorage.getItem('cx-ai-model') || '').trim(); }catch(e){}
  if(forceMdl) mdl = forceMdl;
  const bad = async (resp)=>{ let bd=''; try{ bd=(await resp.text()).replace(/\s+/g,' ').slice(0,120); }catch(e){} window.__aiLastBody = bd; throw new Error('ai ' + resp.status + (bd ? ' | ' + bd : '')); };
  if(prov === 'gemini' && !key && CX_GEM_PROXY){
    const resp = await fetch(CX_GEM_PROXY, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: mdl || CX_AI_DEF.gemini, system, messages: msgs, max_tokens: Math.max(maxTokens || 200, 300) }) });
    if(!resp.ok) await bad(resp);
    const j = await resp.json(); return String(j.text || '').trim();
  }
  if(prov === 'gemini' && !key && !CX_GEM_PROXY) prov = 'proxy';   // koi key/worker nahi => purana proxy
  if(prov !== 'proxy' && !key) throw new Error('ai 401 | ' + prov + ' ki key nahi daali');
  if(prov === 'gemini'){
    const m = mdl || CX_AI_DEF.gemini;
    const resp = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + encodeURIComponent(m) + ':generateContent', { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-goog-api-key': key },
      body: JSON.stringify({ systemInstruction: { parts: [{ text: system }] }, contents: msgs.map(x => ({ role: x.role === 'assistant' ? 'model' : 'user', parts: [{ text: x.content }] })), generationConfig: { maxOutputTokens: Math.max(maxTokens || 200, 300), temperature: 0.8 } }) });
    if(!resp.ok) await bad(resp);
    const j = await resp.json();
    return (((j.candidates || [])[0] || {}).content || { parts: [] }).parts.map(p => p.text || '').join('\n').trim();
  }
  if(prov === 'groq' || prov === 'openrouter'){
    const url = prov === 'groq' ? 'https://api.groq.com/openai/v1/chat/completions' : 'https://openrouter.ai/api/v1/chat/completions';
    const resp = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + key },
      body: JSON.stringify({ model: mdl || CX_AI_DEF[prov], max_tokens: maxTokens || 200, temperature: 0.8, messages: [{ role: 'system', content: system }].concat(msgs) }) });
    if(!resp.ok) await bad(resp);
    const j = await resp.json();
    return String((((j.choices || [])[0] || {}).message || {}).content || '').trim();
  }
  const resp = await fetch(AI_PROXY_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model, max_tokens: maxTokens || 200, system, messages: msgs }) });
  if(!resp.ok) await bad(resp);
  const j = await resp.json();
  return (j.content || []).filter(b => b && b.type === 'text' && b.text).map(b => b.text).join('\n').trim();
}
// ===== AI MODES (Gemini jaisa): Auto / Fast / Smart / Thinking / Pro =====
// Chat AI (reply suggest, Autopilot, AI Partner) sab cxAiCall se guzarte hain, isliye ek jagah mode badalne se sab badal jaate hain.
//  fast  = sabse tez, 1 call            smart = behtar model, 1 call
//  think = pehle <think> me soch, phir reply (soch user ko nahi dikhti)
//  pro   = sabse accha model + soch + doosra "editor" pass jo draft ko polish karta hai
//  auto  = incoming message dekh ke fast/smart/think khud chunta hai
// Kisi bhi step me error aaye to ek neeche ke mode par girta hai (pro->smart->fast) — kabhi pehle se kharab nahi.
const CX_AI_MODES = {
  auto:  { e: '✨', n: 'Auto',     d: 'Message dekh ke khud sahi mode chunta hai' },
  fast:  { e: '⚡', n: 'Fast',     d: 'Sabse tez jawab (1 call)' },
  smart: { e: '🎯', n: 'Smart',    d: 'Tez + behtar model, zyada natural' },
  think: { e: '🧠', n: 'Thinking', d: 'Pehle andar soche, phir reply — mushkil/lambe msgs ke liye' },
  pro:   { e: '💎', n: 'Pro',      d: 'Best model + soch + polish pass (thoda slow, sabse accha)' }
};
const CX_AI_TIER_MODEL = {
  gemini:     { fast: 'gemini-flash-lite-latest', smart: 'gemini-flash-latest', think: 'gemini-flash-latest', pro: 'gemini-pro-latest' },
  groq:       { fast: 'llama-3.1-8b-instant', smart: 'llama-3.3-70b-versatile', think: 'llama-3.3-70b-versatile', pro: 'llama-3.3-70b-versatile' },
  openrouter: { fast: 'meta-llama/llama-3.3-70b-instruct:free', smart: 'meta-llama/llama-3.3-70b-instruct:free', think: 'meta-llama/llama-3.3-70b-instruct:free', pro: 'meta-llama/llama-3.3-70b-instruct:free' },
  proxy:      { fast: 'claude-haiku-4-5', smart: 'claude-sonnet-4-6', think: 'claude-sonnet-4-6', pro: 'claude-sonnet-4-6' }
};
const CX_AI_THINK_ADD_RPT = '\n\nSOCHNE KA TAREEKA (andar ka, user ko nahi dikhega): likhne se PEHLE <think>...</think> ke andar 3-6 chhoti lines me socho: (1) diye gaye data me asli numbers/pattern kya hain, (2) sabse zaroori 2-3 baatein kaun si hain, (3) kya mat likhna (jo data me nahi hai wo andaaza/jhooth na ho). Phir </think> ke BAAD sirf final output do — bilkul wahi format aur lambai jo upar maangi gayi, sochne wali baat final me mat likhna.';
