// Daily Editorial (tools/daily-editorial.html) — single-file offline editorial reader.
// Sirf GitHub par update ki hui bundled HTML khulti hai. Admin upload / Firebase / IndexedDB wala system hata diya.
(function initDailyEditorialPage(){
  const openBtn = document.getElementById('calcDailyEditorialBtn');
  const frame = document.getElementById('dailyeditorialFrame');
  const backBtn = document.getElementById('dailyeditorialBackBtn');
  if(!openBtn || !frame) return;
  // Button par 'kitne article padhe' (editorial ke de_read tick se) dikhao.
  const cntEl = document.getElementById('deReadCnt');
  const upCnt = () => { try{ const n = Object.keys(JSON.parse(localStorage.getItem('de_read')||'{}')).length; if(cntEl) cntEl.textContent = '✅ ' + n + ' padhe'; }catch(e){} };
  upCnt(); window.addEventListener('focus', upCnt); document.addEventListener('visibilitychange', upCnt);
  // Purani admin-uploaded copy (agar kisi phone me saved ho) saaf karo, taaki sirf GitHub wali file khule.
  try{ indexedDB.deleteDatabase('deStore'); }catch(e){}
  openBtn.addEventListener('click', () => {
    showCalcPage('dailyeditorial');
    if(!frame.getAttribute('src')) frame.setAttribute('src', frame.dataset.src + '?t=' + Date.now()); // cache-bust: hamesha GitHub wali fresh file
  });
  // Back handling: editorial ke andar ke screens (home -> list -> reader) parent history se sync hain.
  // Editorial har andar ke step par 'de-push' bhejta hai (hum ek history entry push karte hain);
  // device back par 'de-back' bhejte hain taaki ek screen peeche jaye, app se bahar na nikle.
  const tell = (m) => { try{ frame.contentWindow.postMessage(m,'*'); }catch(e){} };
  const onPage = () => { const a = document.querySelector('.calcPage.active'); return a && a.id === 'calcPage-dailyeditorial'; };
  let dePushed = 0; // editorial ke andar ke kitne steps ne parent history entry push ki
  openBtn.addEventListener('click', () => { dePushed = 0; });
  window.addEventListener('message', (e) => {
    if(e.source !== frame.contentWindow) return;
    if(e.data === 'de-push'){
      try{ history.pushState({cgl50Tab:'calc', calcPage:'dailyeditorial'}, '', location.href); dePushed++; }catch(x){}
    } else if(e.data === 'de-histback'){
      try{ history.back(); }catch(x){}
    } else if(e.data === 'de-exit'){
      try{ history.back(); }catch(x){}
      setTimeout(() => { if(onPage()) showCalcPage('menu', true); }, 180);
    }
  });
  window.addEventListener('popstate', (e) => {
    if(e.state && e.state.calcPage === 'dailyeditorial' && onPage()){ if(dePushed > 0) dePushed--; tell('de-back'); }
    else if(!onPage()) dePushed = 0;
  });
  // App button: editorial ke andar ke saare steps + editorial ki entry ek saath peeche, seedha menu par.
  if(backBtn) backBtn.addEventListener('click', () => {
    tell('de-home'); const n = dePushed + 1; dePushed = 0;
    try{ history.go(-n); }catch(x){}
    setTimeout(() => { if(onPage()) showCalcPage('menu', true); upCnt(); }, 350);
  });
})();
